-- PostgreSQL baseline: equivalent to SQLite migrations 001-022 (final schema).
-- Generated once from the SQLite schema. Add new migrations as new files; do not edit this one.
CREATE EXTENSION IF NOT EXISTS citext;

-- Case- and accent-insensitive search form ("Đông Á" -> "dong a"), same as foldSearchText() in JS.
CREATE OR REPLACE FUNCTION fold(value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT lower(translate(value,
    'àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ',
    'aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyydAAAAAAAAAAAAAAAAAEEEEEEEEEEEIIIIIOOOOOOOOOOOOOOOOOUUUUUUUUUUUYYYYYD'))
$$;
CREATE OR REPLACE FUNCTION search_text(value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT fold(value)
$$;
-- SQLite instr(): 1-based position of needle, 0 when absent.
CREATE OR REPLACE FUNCTION instr(haystack text, needle text) RETURNS integer LANGUAGE sql IMMUTABLE AS $$
  SELECT strpos(haystack, needle)
$$;
-- Shared trigger body for append-only / no-delete rules (SQLite RAISE(ABORT, message)).
CREATE OR REPLACE FUNCTION raise_abort() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '%', TG_ARGV[0] USING ERRCODE = 'restrict_violation';
END
$$;

CREATE TABLE roles (
  code TEXT PRIMARY KEY CHECK(code IN ('A01','A02','A03','A04','A05','A06','A07')),
  name TEXT NOT NULL,
  enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0,1))
);

CREATE TABLE permissions (
  code TEXT PRIMARY KEY,
  module TEXT NOT NULL,
  action TEXT NOT NULL CHECK(action IN ('view','create','edit','approve','export')),
  UNIQUE(module, action)
);

CREATE TABLE role_permissions (
  role_code TEXT NOT NULL REFERENCES roles(code),
  permission_code TEXT NOT NULL REFERENCES permissions(code),
  PRIMARY KEY(role_code, permission_code)
);

CREATE TABLE accounts (
  id TEXT PRIMARY KEY,
  username CITEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  full_name TEXT NOT NULL,
  officer_id TEXT NOT NULL,
  role_code TEXT NOT NULL REFERENCES roles(code),
  status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','locked','inactive')),
  must_change_password BIGINT NOT NULL DEFAULT 1 CHECK(must_change_password IN (0,1)),
  last_login_at BIGINT,
  created_at BIGINT NOT NULL
);

CREATE TABLE units (id TEXT PRIMARY KEY, name TEXT NOT NULL, parent_id TEXT REFERENCES units(id), code CITEXT, level TEXT NOT NULL DEFAULT 'AREA' CHECK(level IN ('ROOT','AREA','WARD')), status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), notes TEXT NOT NULL DEFAULT '' CHECK(length(notes)<=2000), created_at BIGINT NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL DEFAULT 0, leader_officer_id TEXT);

CREATE TABLE regions (id TEXT PRIMARY KEY, name TEXT NOT NULL, unit_id TEXT NOT NULL REFERENCES units(id), code CITEXT, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), notes TEXT NOT NULL DEFAULT '' CHECK(length(notes)<=2000), leader_officer_id TEXT, created_at BIGINT NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL DEFAULT 0);

CREATE TABLE facilities (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL,
  region_id TEXT NOT NULL REFERENCES regions(id),
  officer_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active'
);

CREATE TABLE account_scopes (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES accounts(id),
  kind TEXT NOT NULL CHECK(kind IN ('all','unit','region','facility')),
  unit_id TEXT REFERENCES units(id),
  region_id TEXT REFERENCES regions(id),
  facility_id TEXT REFERENCES facilities(id),
  CHECK((kind='all' AND unit_id IS NULL AND region_id IS NULL AND facility_id IS NULL)
    OR (kind='unit' AND unit_id IS NOT NULL AND region_id IS NULL AND facility_id IS NULL)
    OR (kind='region' AND region_id IS NOT NULL AND unit_id IS NULL AND facility_id IS NULL)
    OR (kind='facility' AND facility_id IS NOT NULL AND unit_id IS NULL AND region_id IS NULL))
);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL
);

CREATE TABLE login_attempts (
  key TEXT PRIMARY KEY, attempts BIGINT NOT NULL, window_start BIGINT NOT NULL
);

CREATE TABLE audit_logs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  actor_id TEXT REFERENCES accounts(id),
  action TEXT NOT NULL, object_id TEXT,
  before_json TEXT, after_json TEXT,
  occurred_at BIGINT NOT NULL, ip TEXT NOT NULL
, feature TEXT NOT NULL DEFAULT 'system', object_type TEXT NOT NULL DEFAULT 'account');

CREATE TABLE officers (
  id TEXT PRIMARY KEY,
  officer_code CITEXT NOT NULL UNIQUE CHECK(length(officer_code) BETWEEN 1 AND 50),
  full_name TEXT NOT NULL CHECK(length(trim(full_name)) BETWEEN 1 AND 150),
  rank TEXT NOT NULL CHECK(length(trim(rank)) BETWEEN 1 AND 100),
  position TEXT NOT NULL CHECK(length(trim(position)) BETWEEN 1 AND 150),
  phone TEXT NOT NULL CHECK(length(phone) BETWEEN 8 AND 25),
  email CITEXT NOT NULL UNIQUE CHECK(length(email) BETWEEN 3 AND 254),
  notes TEXT NOT NULL DEFAULT '' CHECK(length(notes)<=2000),
  unit_id TEXT NOT NULL REFERENCES units(id),
  business_role TEXT NOT NULL REFERENCES roles(code) CHECK(business_role IN ('A01','A02','A03','A04','A05','A06')),
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE','TRANSFERRED')),
  status_reason TEXT,
  status_effective_date TEXT,
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  CHECK(status='ACTIVE' OR (status_reason IS NOT NULL AND status_effective_date IS NOT NULL AND length(trim(status_reason))>0 AND length(status_effective_date)=10))
);

CREATE TABLE incident_types (
  code TEXT PRIMARY KEY NOT NULL CHECK(length(code) BETWEEN 1 AND 50),
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150),
  enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
  configuration_label TEXT NOT NULL DEFAULT 'DEMO_UNCONFIRMED_Q11_Q12'
);

CREATE TABLE incident_subtypes (
  type_code TEXT NOT NULL REFERENCES incident_types(code),
  code TEXT NOT NULL CHECK(length(code) BETWEEN 1 AND 50),
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150),
  enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
  PRIMARY KEY(type_code,code)
);

CREATE TABLE incident_policy (
  id BIGINT PRIMARY KEY CHECK(id=1),
  warning_hours BIGINT NOT NULL DEFAULT 48 CHECK(warning_hours BETWEEN 0 AND 8760),
  require_document_completion BIGINT NOT NULL DEFAULT 0 CHECK(require_document_completion IN (0,1)),
  max_upload_bytes BIGINT NOT NULL DEFAULT 5242880 CHECK(max_upload_bytes BETWEEN 1 AND 52428800),
  allowed_extensions TEXT NOT NULL DEFAULT '["pdf","png","jpg","jpeg","txt"]' CHECK(jsonb_typeof(allowed_extensions::jsonb)='array'),
  configuration_label TEXT NOT NULL DEFAULT 'DEMO_UNCONFIRMED_Q11_Q12',
  updated_by TEXT REFERENCES accounts(id),
  updated_at BIGINT NOT NULL DEFAULT 0 CHECK(updated_at>=0)
);

CREATE TABLE incidents (
  id TEXT PRIMARY KEY NOT NULL CHECK(length(id) BETWEEN 1 AND 128),
  incident_code CITEXT NOT NULL UNIQUE CHECK(length(trim(incident_code)) BETWEEN 1 AND 60),
  incident_type TEXT REFERENCES incident_types(code),
  incident_subtype TEXT,
  title TEXT NOT NULL DEFAULT '' CHECK(length(title)<=250),
  description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=10000),
  occurred_at BIGINT CHECK(occurred_at IS NULL OR (occurred_at>=0)),
  reported_at BIGINT NOT NULL CHECK(reported_at>=0),
  address TEXT NOT NULL DEFAULT '' CHECK(length(address)<=1000),
  scene_details TEXT NOT NULL DEFAULT '' CHECK(length(scene_details)<=20000),
  region_id TEXT REFERENCES regions(id),
  unit_id TEXT REFERENCES units(id),
  facility_id TEXT REFERENCES facilities(id),
  record_status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(record_status IN ('DRAFT','OFFICIAL')),
  processing_status TEXT NOT NULL DEFAULT 'NEW' CHECK(processing_status IN ('NEW','IN_PROGRESS','COMPLETED','CLOSED')),
  deadline_at BIGINT CHECK(deadline_at IS NULL OR (deadline_at>=0)),
  completed_at BIGINT CHECK(completed_at IS NULL OR (completed_at>=0)),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL CHECK(created_at>=0),
  updated_at BIGINT NOT NULL CHECK(updated_at>=0),
  version BIGINT NOT NULL DEFAULT 1 CHECK(version BETWEEN 1 AND 9000000000000000),
  FOREIGN KEY(incident_type,incident_subtype) REFERENCES incident_subtypes(type_code,code),
  CHECK(incident_subtype IS NULL OR incident_type IS NOT NULL),
  CHECK(record_status='DRAFT' OR (incident_type IS NOT NULL AND occurred_at IS NOT NULL AND length(trim(address))>0)),
  CHECK((processing_status IN ('COMPLETED','CLOSED') AND completed_at IS NOT NULL)
    OR (processing_status IN ('NEW','IN_PROGRESS') AND completed_at IS NULL))
);

CREATE TABLE incident_damages (
  id TEXT PRIMARY KEY NOT NULL CHECK(length(id) BETWEEN 1 AND 128),
  incident_id TEXT NOT NULL REFERENCES incidents(id),
  damage_group TEXT NOT NULL CHECK(damage_group IN ('HUMAN','PROPERTY')),
  damage_type TEXT NOT NULL CHECK(length(trim(damage_type)) BETWEEN 1 AND 100),
  quantity BIGINT NOT NULL DEFAULT 0 CHECK(quantity BETWEEN 0 AND 1000000000),
  -- VND whole-number amounts avoid floating-point aggregation errors.
  property_value BIGINT NOT NULL DEFAULT 0 CHECK(property_value BETWEEN 0 AND 9000000000000000),
  description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=2000),
  notes TEXT NOT NULL DEFAULT '' CHECK(length(notes)<=2000),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL CHECK(created_at>=0),
  updated_at BIGINT NOT NULL CHECK(updated_at>=0),
  CHECK(damage_group='PROPERTY' OR property_value=0)
);

CREATE TABLE incident_assignments (
  id TEXT PRIMARY KEY NOT NULL CHECK(length(id) BETWEEN 1 AND 128),
  incident_id TEXT NOT NULL REFERENCES incidents(id),
  officer_id TEXT NOT NULL REFERENCES officers(id),
  assigned_by TEXT NOT NULL REFERENCES accounts(id),
  task_description TEXT NOT NULL CHECK(length(trim(task_description)) BETWEEN 1 AND 4000),
  deadline_at BIGINT CHECK(deadline_at IS NULL OR (deadline_at>=0)),
  status TEXT NOT NULL DEFAULT 'ASSIGNED' CHECK(status IN ('ASSIGNED','IN_PROGRESS','COMPLETED','CANCELLED')),
  notes TEXT NOT NULL DEFAULT '' CHECK(length(notes)<=2000),
  assigned_at BIGINT NOT NULL CHECK(assigned_at>=0),
  completed_at BIGINT CHECK(completed_at IS NULL OR (completed_at>=0)),
  updated_at BIGINT NOT NULL CHECK(updated_at>=0),
  CHECK((status='COMPLETED' AND completed_at IS NOT NULL) OR (status<>'COMPLETED' AND completed_at IS NULL))
);

CREATE TABLE incident_documents (
  id TEXT PRIMARY KEY NOT NULL CHECK(length(id) BETWEEN 1 AND 128),
  incident_id TEXT NOT NULL REFERENCES incidents(id),
  original_name TEXT NOT NULL CHECK(length(original_name) BETWEEN 1 AND 255),
  stored_name TEXT NOT NULL UNIQUE CHECK(length(stored_name) BETWEEN 1 AND 255),
  file_type TEXT NOT NULL CHECK(length(file_type) BETWEEN 1 AND 50),
  mime_type TEXT NOT NULL CHECK(length(mime_type) BETWEEN 3 AND 100),
  size_bytes BIGINT NOT NULL CHECK(size_bytes BETWEEN 1 AND 52428800),
  -- Keys are opaque file names inside a private upload directory, never URLs.
  storage_key TEXT NOT NULL UNIQUE CHECK(length(storage_key) BETWEEN 1 AND 255 AND instr(storage_key,'..')=0 AND instr(storage_key,'/')=0 AND instr(storage_key,chr(92))=0),
  uploaded_by TEXT NOT NULL REFERENCES accounts(id),
  uploaded_at BIGINT NOT NULL CHECK(uploaded_at>=0)
);

CREATE TABLE incident_status_history (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  incident_id TEXT NOT NULL REFERENCES incidents(id),
  from_status TEXT CHECK(from_status IS NULL OR from_status IN ('NEW','IN_PROGRESS','COMPLETED','CLOSED')),
  to_status TEXT NOT NULL CHECK(to_status IN ('NEW','IN_PROGRESS','COMPLETED','CLOSED')),
  from_record_status TEXT CHECK(from_record_status IS NULL OR from_record_status IN ('DRAFT','OFFICIAL')),
  to_record_status TEXT NOT NULL CHECK(to_record_status IN ('DRAFT','OFFICIAL')),
  old_deadline_at BIGINT CHECK(old_deadline_at IS NULL OR (old_deadline_at>=0)),
  new_deadline_at BIGINT CHECK(new_deadline_at IS NULL OR (new_deadline_at>=0)),
  changed_by TEXT NOT NULL REFERENCES accounts(id),
  changed_at BIGINT NOT NULL CHECK(changed_at>=0),
  reason TEXT NOT NULL DEFAULT '' CHECK(length(reason)<=2000),
  notes TEXT NOT NULL DEFAULT '' CHECK(length(notes)<=2000)
);

CREATE TABLE legal_document_categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE CHECK(length(trim(name)) BETWEEN 1 AND 100)
);

CREATE TABLE legal_documents (
  id TEXT PRIMARY KEY,
  category_id TEXT NOT NULL REFERENCES legal_document_categories(id),
  title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 500),
  reference_number CITEXT NOT NULL UNIQUE CHECK(length(trim(reference_number)) BETWEEN 1 AND 100),
  issuing_authority TEXT NOT NULL CHECK(length(trim(issuing_authority)) BETWEEN 1 AND 200),
  issued_date TEXT,
  effective_date TEXT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('effective','expired','pending')),
  source_url TEXT,
  file_name TEXT,
  file_data BYTEA,
  notes TEXT NOT NULL DEFAULT '',
  version BIGINT NOT NULL DEFAULT 1 CHECK(version > 0),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  CHECK(source_url IS NOT NULL OR file_data IS NOT NULL),
  CHECK((file_data IS NULL AND file_name IS NULL) OR (file_data IS NOT NULL AND file_name IS NOT NULL))
);

CREATE TABLE inspection_checklists (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),
  -- NULL = applies to every facility type; otherwise a facility-type label (configurable catalog).
  facility_type TEXT CHECK(facility_type IS NULL OR length(trim(facility_type)) BETWEEN 1 AND 100),
  description TEXT NOT NULL DEFAULT '',
  -- Optional link to the guidance document in the M05 library.
  legal_document_id TEXT REFERENCES legal_documents(id),
  is_active BIGINT NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),
  created_at BIGINT NOT NULL
, created_by TEXT REFERENCES accounts(id));

CREATE TABLE inspection_checklist_items (
  id TEXT PRIMARY KEY,
  checklist_id TEXT NOT NULL REFERENCES inspection_checklists(id),
  position BIGINT NOT NULL CHECK(position > 0),
  content TEXT NOT NULL CHECK(length(trim(content)) BETWEEN 1 AND 500),
  guidance TEXT NOT NULL DEFAULT '',
  legal_reference TEXT NOT NULL DEFAULT '',
  is_required BIGINT NOT NULL DEFAULT 1 CHECK(is_required IN (0,1)),
  UNIQUE(checklist_id, position)
);

CREATE TABLE inspection_plans (
  id TEXT PRIMARY KEY,
  code CITEXT NOT NULL UNIQUE,
  year BIGINT NOT NULL CHECK(year BETWEEN 2000 AND 2100),
  title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300),
  facility_group TEXT NOT NULL DEFAULT '',
  legal_basis TEXT NOT NULL DEFAULT '',
  unit_id TEXT NOT NULL REFERENCES units(id),
  annual_target BIGINT NOT NULL CHECK(annual_target > 0),
  status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed')),
  version BIGINT NOT NULL DEFAULT 1 CHECK(version > 0),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
);

CREATE TABLE inspection_targets (
  id TEXT PRIMARY KEY,
  plan_id TEXT NOT NULL REFERENCES inspection_plans(id),
  parent_id TEXT REFERENCES inspection_targets(id),
  period_type TEXT NOT NULL CHECK(period_type IN ('year','month','week')),
  year BIGINT NOT NULL CHECK(year BETWEEN 2000 AND 2100),
  month BIGINT CHECK(month BETWEEN 1 AND 12),
  week BIGINT CHECK(week BETWEEN 1 AND 53),
  officer_id TEXT REFERENCES officers(id),
  region_id TEXT REFERENCES regions(id),
  target_count BIGINT NOT NULL CHECK(target_count > 0),
  carryover_count BIGINT NOT NULL DEFAULT 0 CHECK(carryover_count >= 0),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  CHECK((period_type='year' AND month IS NULL AND week IS NULL)
    OR (period_type='month' AND month IS NOT NULL AND week IS NULL)
    OR (period_type='week' AND month IS NOT NULL AND week IS NOT NULL))
);

CREATE TABLE inspections (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  facility_id TEXT NOT NULL REFERENCES facilities(id),
  kind TEXT NOT NULL CHECK(kind IN ('periodic','unscheduled','thematic')),
  topic TEXT,
  reason TEXT NOT NULL DEFAULT '',
  scheduled_date TEXT NOT NULL,
  lead_officer_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','completed')),
  checklist_id TEXT REFERENCES inspection_checklists(id),
  officer_note TEXT NOT NULL DEFAULT '',
  outcome TEXT CHECK(outcome IS NULL OR outcome IN ('pass','conditional','fail')),
  conclusion TEXT NOT NULL DEFAULT '',
  completed_at BIGINT,
  completed_by TEXT REFERENCES accounts(id),
  version BIGINT NOT NULL DEFAULT 1 CHECK(version > 0),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL, results_submitted_at BIGINT, results_submitted_by TEXT REFERENCES accounts(id), plan_id TEXT REFERENCES inspection_plans(id), target_id TEXT REFERENCES inspection_targets(id),
  CHECK(kind <> 'thematic' OR length(trim(coalesce(topic,''))) > 0),
  CHECK(status <> 'completed' OR (outcome IS NOT NULL AND completed_at IS NOT NULL))
);

CREATE TABLE inspection_results (
  inspection_id TEXT NOT NULL REFERENCES inspections(id),
  item_id TEXT NOT NULL REFERENCES inspection_checklist_items(id),
  status TEXT NOT NULL CHECK(status IN ('pending','pass','fail','not_applicable')),
  note TEXT NOT NULL DEFAULT '',
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  updated_at BIGINT NOT NULL,
  PRIMARY KEY(inspection_id, item_id)
);

CREATE TABLE follow_up_inspections (
  id TEXT PRIMARY KEY,
  inspection_id TEXT NOT NULL REFERENCES inspections(id),
  requirement TEXT NOT NULL CHECK(length(trim(requirement)) BETWEEN 1 AND 2000),
  due_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed')),
  outcome TEXT CHECK(outcome IS NULL OR outcome IN ('resolved','unresolved')),
  result_note TEXT NOT NULL DEFAULT '',
  created_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  completed_by TEXT REFERENCES accounts(id),
  completed_at BIGINT,
  CHECK((status='open' AND outcome IS NULL AND completed_at IS NULL)
    OR (status='completed' AND outcome IS NOT NULL AND completed_at IS NOT NULL))
);

CREATE TABLE inspection_documents (
  id TEXT PRIMARY KEY,
  inspection_id TEXT NOT NULL REFERENCES inspections(id),
  follow_up_id TEXT REFERENCES follow_up_inspections(id),
  kind TEXT NOT NULL CHECK(kind IN ('record','evidence')),
  record_number TEXT,
  description TEXT NOT NULL DEFAULT '',
  file_name TEXT NOT NULL,
  content_type TEXT NOT NULL CHECK(content_type IN ('application/pdf','image/jpeg','image/png')),
  file_size BIGINT NOT NULL CHECK(file_size > 0),
  file_data BYTEA NOT NULL,
  uploaded_by TEXT NOT NULL REFERENCES accounts(id),
  uploaded_at BIGINT NOT NULL
);

CREATE TABLE inspection_schedules (
  id TEXT PRIMARY KEY,
  inspection_id TEXT NOT NULL UNIQUE REFERENCES inspections(id),
  scheduled_date TEXT NOT NULL,
  start_time TEXT,
  end_time TEXT,
  location TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','rescheduled','cancelled')),
  version BIGINT NOT NULL DEFAULT 1 CHECK(version > 0),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  CHECK(start_time IS NULL OR length(start_time)=5),
  CHECK(end_time IS NULL OR length(end_time)=5)
);

CREATE TABLE inspection_reschedules (
  id TEXT PRIMARY KEY,
  inspection_id TEXT NOT NULL REFERENCES inspections(id),
  schedule_id TEXT NOT NULL REFERENCES inspection_schedules(id),
  old_date TEXT NOT NULL,
  new_date TEXT NOT NULL,
  old_start_time TEXT,
  new_start_time TEXT,
  old_end_time TEXT,
  new_end_time TEXT,
  reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 2000),
  attachment_name TEXT,
  attachment_type TEXT CHECK(attachment_type IS NULL OR attachment_type IN ('application/pdf','image/jpeg','image/png')),
  attachment_size BIGINT CHECK(attachment_size IS NULL OR attachment_size > 0),
  attachment_data BYTEA,
  changed_by TEXT NOT NULL REFERENCES accounts(id),
  changed_at BIGINT NOT NULL,
  CHECK((attachment_name IS NULL AND attachment_type IS NULL AND attachment_size IS NULL AND attachment_data IS NULL)
    OR (attachment_name IS NOT NULL AND attachment_type IS NOT NULL AND attachment_size IS NOT NULL AND attachment_data IS NOT NULL))
);

CREATE TABLE inspection_notices (
  id TEXT PRIMARY KEY,
  inspection_id TEXT NOT NULL UNIQUE REFERENCES inspections(id),
  notice_number TEXT NOT NULL DEFAULT '',
  recipient_name TEXT NOT NULL CHECK(length(trim(recipient_name)) BETWEEN 1 AND 200),
  recipient_contact TEXT NOT NULL DEFAULT '',
  notice_text TEXT NOT NULL DEFAULT '',
  sent_date TEXT,
  inspection_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent')),
  file_name TEXT,
  content_type TEXT CHECK(content_type IS NULL OR content_type IN ('application/pdf','image/jpeg','image/png')),
  file_size BIGINT CHECK(file_size IS NULL OR file_size > 0),
  file_data BYTEA,
  version BIGINT NOT NULL DEFAULT 1 CHECK(version > 0),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  CHECK(status='draft' OR sent_date IS NOT NULL),
  CHECK((file_name IS NULL AND content_type IS NULL AND file_size IS NULL AND file_data IS NULL)
    OR (file_name IS NOT NULL AND content_type IS NOT NULL AND file_size IS NOT NULL AND file_data IS NOT NULL))
);

CREATE TABLE inspection_planning_documents (
  id TEXT PRIMARY KEY,
  inspection_id TEXT NOT NULL REFERENCES inspections(id),
  kind TEXT NOT NULL CHECK(kind IN ('team_decision')),
  description TEXT NOT NULL DEFAULT '',
  file_name TEXT NOT NULL,
  content_type TEXT NOT NULL CHECK(content_type IN ('application/pdf','image/jpeg','image/png')),
  file_size BIGINT NOT NULL CHECK(file_size > 0),
  file_data BYTEA NOT NULL,
  uploaded_by TEXT NOT NULL REFERENCES accounts(id),
  uploaded_at BIGINT NOT NULL
);

CREATE TABLE region_assignments (
  region_id TEXT PRIMARY KEY REFERENCES regions(id),
  account_id TEXT NOT NULL REFERENCES accounts(id),
  assigned_at BIGINT NOT NULL
);

CREATE TABLE account_transfers (
  id TEXT PRIMARY KEY,
  source_account_id TEXT NOT NULL REFERENCES accounts(id),
  target_account_id TEXT NOT NULL REFERENCES accounts(id),
  source_officer_id TEXT NOT NULL,
  target_officer_id TEXT NOT NULL,
  effective_at BIGINT NOT NULL,
  performed_by TEXT NOT NULL REFERENCES accounts(id),
  reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 1000),
  created_at BIGINT NOT NULL,
  audit_log_id BIGINT NOT NULL UNIQUE REFERENCES audit_logs(id),
  CHECK(source_account_id <> target_account_id)
);

CREATE TABLE account_transfer_items (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  transfer_id TEXT NOT NULL REFERENCES account_transfers(id),
  region_id TEXT REFERENCES regions(id),
  facility_id TEXT REFERENCES facilities(id),
  source_officer_id TEXT NOT NULL,
  target_officer_id TEXT NOT NULL,
  CHECK((region_id IS NOT NULL AND facility_id IS NULL)
     OR (region_id IS NULL AND facility_id IS NOT NULL))
);

CREATE TABLE assignment_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  region_id TEXT REFERENCES regions(id),
  facility_id TEXT REFERENCES facilities(id),
  from_account_id TEXT REFERENCES accounts(id),
  to_account_id TEXT REFERENCES accounts(id),
  action TEXT NOT NULL CHECK(action IN ('assign','unassign')),
  reason TEXT,
  effective_date TEXT,
  performed_by TEXT NOT NULL REFERENCES accounts(id),
  occurred_at BIGINT NOT NULL,
  audit_log_id BIGINT,
  CHECK((region_id IS NOT NULL AND facility_id IS NULL)
     OR (region_id IS NULL AND facility_id IS NOT NULL))
);

CREATE TABLE facility_status_history (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  facility_id TEXT NOT NULL REFERENCES facilities(id),
  previous_status TEXT NOT NULL,
  new_status TEXT NOT NULL,
  reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 1000),
  decision_reference TEXT,
  actor_id TEXT NOT NULL REFERENCES accounts(id),
  occurred_at BIGINT NOT NULL,
  audit_log_id BIGINT NOT NULL UNIQUE REFERENCES audit_logs(id),
  CHECK(previous_status <> new_status)
);

CREATE TABLE facility_violations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  facility_id TEXT NOT NULL REFERENCES facilities(id),
  description TEXT NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 1000),
  suspension_decision_reference TEXT NOT NULL CHECK(length(trim(suspension_decision_reference)) BETWEEN 1 AND 200),
  suspension_at BIGINT NOT NULL,
  suspended_by TEXT NOT NULL REFERENCES accounts(id),
  status TEXT NOT NULL DEFAULT 'suspended' CHECK(status IN ('suspended','restored')),
  remediation_evidence TEXT,
  restoration_decision_reference TEXT,
  approved_by TEXT REFERENCES accounts(id),
  approved_at BIGINT,
  CHECK((status='suspended' AND approved_by IS NULL AND approved_at IS NULL AND restoration_decision_reference IS NULL)
    OR (status='restored' AND approved_by IS NOT NULL AND approved_at IS NOT NULL
      AND remediation_evidence IS NOT NULL AND restoration_decision_reference IS NOT NULL
      AND length(trim(remediation_evidence)) > 0 AND length(trim(restoration_decision_reference)) > 0))
);

CREATE TABLE tasks (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200),
  description TEXT NOT NULL DEFAULT '',
  assigned_by TEXT NOT NULL REFERENCES accounts(id),
  assigned_to TEXT NOT NULL REFERENCES accounts(id),
  status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed','cancelled')),
  created_at BIGINT NOT NULL
, kind TEXT NOT NULL DEFAULT 'assigned'
  CHECK(kind IN ('routine','unscheduled','assigned')), due_at BIGINT, progress BIGINT NOT NULL DEFAULT 0
  CHECK(progress BETWEEN 0 AND 100), updated_at BIGINT, completed_at BIGINT);

CREATE TABLE task_messages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id TEXT NOT NULL REFERENCES tasks(id),
  sender_id TEXT NOT NULL REFERENCES accounts(id),
  body TEXT NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 2000),
  created_at BIGINT NOT NULL,
  edited_at BIGINT,
  deleted_at BIGINT,
  deleted_by TEXT REFERENCES accounts(id),
  seed_key TEXT UNIQUE,
  CHECK((deleted_at IS NULL AND deleted_by IS NULL) OR (deleted_at IS NOT NULL AND deleted_by IS NOT NULL))
);

CREATE TABLE task_assignments (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id TEXT NOT NULL REFERENCES tasks(id),
  assignee_id TEXT NOT NULL REFERENCES accounts(id),
  assigned_by TEXT NOT NULL REFERENCES accounts(id),
  assigned_at BIGINT NOT NULL,
  ended_at BIGINT,
  note TEXT,
  CHECK(ended_at IS NULL OR ended_at >= assigned_at)
);

CREATE TABLE task_progress (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id TEXT NOT NULL REFERENCES tasks(id),
  account_id TEXT NOT NULL REFERENCES accounts(id),
  progress BIGINT NOT NULL CHECK(progress BETWEEN 0 AND 100),
  status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed','cancelled')),
  note TEXT,
  created_at BIGINT NOT NULL
);

CREATE TABLE kpi_targets (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES accounts(id),
  period TEXT NOT NULL CHECK(period ~ '^[0-9]{4}-[0-9]{2}$'),
  target_tasks BIGINT NOT NULL CHECK(target_tasks BETWEEN 0 AND 10000),
  note TEXT,
  created_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  UNIQUE(account_id,period)
);

CREATE TABLE kpi_results (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES accounts(id),
  period TEXT NOT NULL,
  target_tasks BIGINT NOT NULL,
  completed_tasks BIGINT NOT NULL,
  previous_debt BIGINT NOT NULL,
  debt BIGINT NOT NULL,
  waived_debt BIGINT NOT NULL DEFAULT 0,
  score BIGINT NOT NULL,
  computed_at BIGINT NOT NULL,
  UNIQUE(account_id,period)
);

CREATE TABLE explanations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  task_id TEXT REFERENCES tasks(id),
  account_id TEXT NOT NULL REFERENCES accounts(id),
  period TEXT,
  requested_by TEXT NOT NULL REFERENCES accounts(id),
  reason TEXT NOT NULL,
  response TEXT,
  status TEXT NOT NULL DEFAULT 'requested'
    CHECK(status IN ('requested','submitted','accepted','rejected')),
  requested_at BIGINT NOT NULL,
  submitted_at BIGINT,
  reviewed_by TEXT REFERENCES accounts(id),
  reviewed_at BIGINT,
  review_note TEXT,
  debt_waived BIGINT NOT NULL DEFAULT 0 CHECK(debt_waived IN (0,1)),
  seed_key TEXT UNIQUE,
  CHECK(task_id IS NOT NULL OR period IS NOT NULL),
  CHECK(period IS NULL OR period ~ '^[0-9]{4}-[0-9]{2}$')
);

CREATE TABLE data_transfer_jobs (
  id TEXT PRIMARY KEY,
  direction TEXT NOT NULL CHECK(direction IN ('import','export')),
  dataset_id TEXT NOT NULL,
  file_name TEXT NOT NULL,
  file_format TEXT NOT NULL CHECK(file_format IN ('csv','xlsx')),
  status TEXT NOT NULL CHECK(status IN (
    'validating','preview_ready','importing','succeeded','partial','failed'
  )),
  filters_json TEXT NOT NULL DEFAULT '{}',
  total_records BIGINT NOT NULL DEFAULT 0 CHECK(total_records >= 0),
  successful_records BIGINT NOT NULL DEFAULT 0 CHECK(successful_records >= 0),
  error_count BIGINT NOT NULL DEFAULT 0 CHECK(error_count >= 0),
  error_summary TEXT,
  actor_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
  created_at BIGINT NOT NULL,
  completed_at BIGINT,
  CHECK(successful_records + error_count <= total_records)
);

CREATE TABLE data_transfer_errors (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES data_transfer_jobs(id) ON DELETE RESTRICT,
  row_number BIGINT NOT NULL CHECK(row_number > 0),
  field_name TEXT,
  error_code TEXT,
  message TEXT NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 1000),
  created_at BIGINT NOT NULL
);

CREATE TABLE facility_personnel (
  id TEXT PRIMARY KEY,
  facility_id TEXT NOT NULL REFERENCES facilities(id),
  full_name TEXT NOT NULL CHECK(length(trim(full_name)) BETWEEN 1 AND 150),
  position TEXT NOT NULL CHECK(length(trim(position)) BETWEEN 1 AND 150),
  phone TEXT CHECK(phone IS NULL OR length(phone) BETWEEN 8 AND 25),
  email TEXT CHECK(email IS NULL OR length(email) BETWEEN 3 AND 254),
  is_head BIGINT NOT NULL DEFAULT 0 CHECK(is_head IN (0,1)),
  training_status TEXT CHECK(training_status IS NULL OR length(training_status) <= 100),
  certificate_expiry TEXT CHECK(
    certificate_expiry IS NULL OR
    (length(certificate_expiry)=10 AND certificate_expiry ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
  ),
  notes TEXT NOT NULL DEFAULT '' CHECK(length(notes) <= 2000),
  is_active BIGINT NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),
  version BIGINT NOT NULL DEFAULT 1 CHECK(version >= 1),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  updated_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL, certificate_number TEXT CHECK(
  certificate_number IS NULL OR length(trim(certificate_number)) BETWEEN 1 AND 100
),
  UNIQUE(id, facility_id),
  CHECK(is_head=0 OR is_active=1)
);

CREATE TABLE report_types (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),
  description TEXT NOT NULL DEFAULT '',
  cycle TEXT NOT NULL CHECK(cycle IN ('once','weekly','monthly','quarterly','yearly')),
  warning_days BIGINT NOT NULL DEFAULT 5 CHECK(warning_days BETWEEN 0 AND 90),
  active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
);

CREATE TABLE report_schedules (
  id TEXT PRIMARY KEY,
  report_type_id TEXT NOT NULL REFERENCES report_types(id),
  assignee_id TEXT NOT NULL REFERENCES accounts(id),
  requester_id TEXT NOT NULL REFERENCES accounts(id),
  recipient TEXT NOT NULL,
  reference_number TEXT,
  next_due_date TEXT NOT NULL,
  active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
);

CREATE TABLE report_requests (
  id TEXT PRIMARY KEY,
  report_type_id TEXT NOT NULL REFERENCES report_types(id),
  schedule_id TEXT REFERENCES report_schedules(id),
  period_key TEXT,
  title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200),
  recipient TEXT NOT NULL,
  reference_number TEXT,
  requester_id TEXT NOT NULL REFERENCES accounts(id),
  assignee_id TEXT NOT NULL REFERENCES accounts(id),
  due_date TEXT NOT NULL,
  warning_days BIGINT NOT NULL CHECK(warning_days BETWEEN 0 AND 90),
  status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','submitted','completed','cancelled')),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  completed_at BIGINT,
  UNIQUE(schedule_id,period_key)
);

CREATE TABLE report_submissions (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL REFERENCES report_requests(id),
  submitted_by TEXT NOT NULL REFERENCES accounts(id),
  note TEXT NOT NULL DEFAULT '',
  file_name TEXT NOT NULL,
  content_type TEXT NOT NULL,
  file_size BIGINT NOT NULL CHECK(file_size BETWEEN 1 AND 10485760),
  file_data BYTEA NOT NULL,
  submitted_at BIGINT NOT NULL
);

CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES accounts(id),
  feature TEXT NOT NULL,
  kind TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  target_path TEXT,
  object_id TEXT,
  dedupe_key TEXT UNIQUE,
  created_at BIGINT NOT NULL,
  read_at BIGINT
);

CREATE TABLE violations (
  id TEXT PRIMARY KEY,
  facility_id TEXT NOT NULL REFERENCES facilities(id),
  violation_type TEXT NOT NULL,
  severity TEXT NOT NULL CHECK(severity IN ('Nhẹ','Trung bình','Nghiêm trọng')),
  detected_on TEXT NOT NULL,
  description TEXT NOT NULL,
  facility_condition TEXT NOT NULL DEFAULT 'violation'
    CHECK(facility_condition IN ('violation','unlicensed','insufficient')),
  remediation_deadline TEXT,
  tracked_officer_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'recorded'
    CHECK(status IN ('recorded','remediation','pending_approval','returned','completed')),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
);

CREATE TABLE suspensions (
  id TEXT PRIMARY KEY,
  violation_id TEXT NOT NULL UNIQUE REFERENCES violations(id),
  decision_number TEXT NOT NULL,
  reason TEXT NOT NULL,
  issued_on TEXT NOT NULL,
  effective_until TEXT,
  previous_facility_status TEXT NOT NULL,
  created_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
);

CREATE TABLE remediation_records (
  id TEXT PRIMARY KEY,
  violation_id TEXT NOT NULL REFERENCES violations(id),
  note TEXT NOT NULL,
  progress BIGINT NOT NULL CHECK(progress BETWEEN 0 AND 100),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL
);

CREATE TABLE violation_evidences (
  id TEXT PRIMARY KEY,
  violation_id TEXT NOT NULL REFERENCES violations(id),
  file_name TEXT NOT NULL,
  media_type TEXT NOT NULL,
  file_size BIGINT NOT NULL CHECK(file_size > 0),
  content BYTEA NOT NULL,
  uploaded_by TEXT NOT NULL REFERENCES accounts(id),
  uploaded_at BIGINT NOT NULL
);

CREATE TABLE violation_status_history (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  violation_id TEXT NOT NULL REFERENCES violations(id),
  from_status TEXT,
  to_status TEXT NOT NULL,
  reason TEXT,
  actor_id TEXT NOT NULL REFERENCES accounts(id),
  occurred_at BIGINT NOT NULL
);

CREATE TABLE attachments (
  id TEXT PRIMARY KEY,
  facility_id TEXT NOT NULL REFERENCES facilities(id),
  personnel_id TEXT,
  document_type TEXT NOT NULL CHECK(length(trim(document_type)) BETWEEN 1 AND 100),
  description TEXT NOT NULL DEFAULT '' CHECK(length(description) <= 1000),
  original_name TEXT NOT NULL CHECK(length(original_name) BETWEEN 1 AND 200),
  stored_name TEXT NOT NULL UNIQUE,
  content_type TEXT NOT NULL CHECK(content_type IN (
    'application/pdf',
    'image/jpeg',
    'image/png',
    'image/gif',
    'image/webp',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  )),
  size_bytes BIGINT NOT NULL CHECK(size_bytes > 0),
  storage_path TEXT NOT NULL UNIQUE,
  checksum TEXT CHECK(checksum IS NULL OR (length(checksum)=64 AND checksum ~ '^[a-f0-9]*$')),
  issue_date TEXT CHECK(issue_date IS NULL OR (length(issue_date)=10 AND issue_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')),
  expiry_date TEXT CHECK(expiry_date IS NULL OR (length(expiry_date)=10 AND expiry_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')),
  uploaded_by TEXT NOT NULL REFERENCES accounts(id),
  uploaded_at BIGINT NOT NULL,
  deleted_at BIGINT,
  deleted_by TEXT REFERENCES accounts(id),
  FOREIGN KEY(personnel_id,facility_id) REFERENCES facility_personnel(id,facility_id),
  CHECK((deleted_at IS NULL AND deleted_by IS NULL) OR (deleted_at IS NOT NULL AND deleted_by IS NOT NULL)),
  CHECK(issue_date IS NULL OR expiry_date IS NULL OR expiry_date >= issue_date)
);

CREATE TABLE report_export_types (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),
  description TEXT NOT NULL DEFAULT '',
  dataset_key TEXT NOT NULL
    CHECK(dataset_key IN ('facilities','violations','inspections','tasks')),
  scope_kind TEXT NOT NULL CHECK(scope_kind IN ('facility','account')),
  supports_period BIGINT NOT NULL DEFAULT 1 CHECK(supports_period IN (0,1)),
  supports_region BIGINT NOT NULL DEFAULT 0 CHECK(supports_region IN (0,1)),
  default_format TEXT NOT NULL DEFAULT 'xlsx' CHECK(default_format IN ('xlsx','pdf')),
  is_active BIGINT NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),
  created_at BIGINT NOT NULL
);

CREATE TABLE report_templates (
  id TEXT PRIMARY KEY,
  report_type_id TEXT NOT NULL REFERENCES report_export_types(id),
  name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),
  format TEXT NOT NULL CHECK(format IN ('xlsx','pdf')),
  title TEXT NOT NULL DEFAULT '' CHECK(length(title) <= 300),
  header_note TEXT NOT NULL DEFAULT '' CHECK(length(header_note) <= 1000),
  footer_note TEXT NOT NULL DEFAULT '' CHECK(length(footer_note) <= 1000),
  column_labels_json TEXT NOT NULL DEFAULT '{}',
  is_official BIGINT NOT NULL DEFAULT 0 CHECK(is_official IN (0,1)),
  is_active BIGINT NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)),
  created_by TEXT NOT NULL REFERENCES accounts(id),
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL
);

CREATE TABLE report_export_requests (
  id TEXT PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  report_type_id TEXT NOT NULL REFERENCES report_export_types(id),
  requested_by TEXT NOT NULL REFERENCES accounts(id),
  period_start TEXT,
  period_end TEXT,
  filters_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'processing'
    CHECK(status IN ('processing','completed','failed')),
  created_at BIGINT NOT NULL,
  completed_at BIGINT,
  CHECK(period_start IS NULL OR period_end IS NULL OR period_start <= period_end)
);

CREATE TABLE report_export_submissions (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL UNIQUE REFERENCES report_export_requests(id),
  file_name TEXT NOT NULL CHECK(length(trim(file_name)) BETWEEN 1 AND 255),
  content_type TEXT NOT NULL,
  file_size BIGINT NOT NULL CHECK(file_size > 0),
  file_data BYTEA NOT NULL,
  created_at BIGINT NOT NULL
);

CREATE TABLE report_export_history (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL UNIQUE REFERENCES report_export_requests(id),
  submission_id TEXT UNIQUE REFERENCES report_export_submissions(id),
  report_type_id TEXT NOT NULL REFERENCES report_export_types(id),
  template_id TEXT REFERENCES report_templates(id),
  template_name TEXT,
  format TEXT NOT NULL CHECK(format IN ('xlsx','pdf')),
  file_name TEXT,
  file_size BIGINT,
  row_count BIGINT NOT NULL DEFAULT 0 CHECK(row_count >= 0),
  filters_json TEXT NOT NULL DEFAULT '{}',
  period_start TEXT,
  period_end TEXT,
  exported_by TEXT NOT NULL REFERENCES accounts(id),
  exported_at BIGINT NOT NULL,
  status TEXT NOT NULL CHECK(status IN ('completed','failed')),
  error_message TEXT,
  CHECK(status <> 'failed' OR (error_message IS NOT NULL AND length(trim(error_message)) > 0)),
  CHECK(status <> 'completed' OR (submission_id IS NOT NULL AND file_name IS NOT NULL))
);

ALTER TABLE units ADD FOREIGN KEY (leader_officer_id) REFERENCES officers(id);
ALTER TABLE regions ADD FOREIGN KEY (leader_officer_id) REFERENCES officers(id);

