CREATE UNIQUE INDEX regions_code_unique_idx ON regions(code);
CREATE INDEX units_leader_idx ON units(leader_officer_id);
CREATE INDEX regions_leader_idx ON regions(leader_officer_id);
CREATE INDEX incidents_occurred_idx ON incidents(occurred_at);
CREATE INDEX incidents_type_occurred_idx ON incidents(incident_type,occurred_at);
CREATE INDEX incidents_record_processing_idx ON incidents(record_status,processing_status);
CREATE INDEX incidents_region_idx ON incidents(region_id);
CREATE INDEX incidents_unit_idx ON incidents(unit_id);
CREATE INDEX incidents_facility_idx ON incidents(facility_id);
CREATE INDEX incidents_deadline_idx ON incidents(deadline_at,processing_status);
CREATE INDEX incidents_creator_idx ON incidents(created_by);
CREATE INDEX incident_damages_incident_idx ON incident_damages(incident_id);
CREATE INDEX incident_damages_type_idx ON incident_damages(damage_group,damage_type);
CREATE INDEX incident_assignments_incident_idx ON incident_assignments(incident_id);
CREATE INDEX incident_assignments_officer_status_idx ON incident_assignments(officer_id,status);
CREATE INDEX incident_assignments_deadline_idx ON incident_assignments(deadline_at,status);
CREATE INDEX incident_documents_incident_idx ON incident_documents(incident_id,uploaded_at);
CREATE INDEX incident_status_history_incident_idx ON incident_status_history(incident_id,changed_at);
CREATE INDEX audit_logs_actor_time_idx ON audit_logs(actor_id, occurred_at);
CREATE INDEX audit_logs_feature_time_idx ON audit_logs(feature, occurred_at);
CREATE INDEX audit_logs_action_time_idx ON audit_logs(action, occurred_at);
CREATE INDEX audit_logs_object_idx ON audit_logs(object_type, object_id, id);
CREATE INDEX legal_documents_category_status_idx ON legal_documents(category_id, status);
CREATE INDEX legal_documents_updated_idx ON legal_documents(updated_at, id);
CREATE INDEX inspection_checklists_type_idx ON inspection_checklists(is_active, facility_type);
CREATE INDEX inspections_facility_idx ON inspections(facility_id, scheduled_date);
CREATE INDEX inspections_status_idx ON inspections(status, scheduled_date);
CREATE INDEX inspection_documents_inspection_idx ON inspection_documents(inspection_id, uploaded_at);
CREATE INDEX follow_up_inspections_inspection_idx ON follow_up_inspections(inspection_id, created_at);
CREATE UNIQUE INDEX follow_up_inspections_open_idx ON follow_up_inspections(inspection_id) WHERE status='open';
CREATE UNIQUE INDEX inspection_checklists_active_name_idx
  ON inspection_checklists(lower(name), coalesce(facility_type,'')) WHERE is_active=1;
CREATE INDEX inspection_plans_year_idx ON inspection_plans(year, unit_id, status);
CREATE UNIQUE INDEX inspection_targets_unique_idx ON inspection_targets(
  plan_id, period_type, year, coalesce(month,0), coalesce(week,0),
  coalesce(officer_id,''), coalesce(region_id,'')
);
CREATE INDEX inspection_targets_plan_idx ON inspection_targets(plan_id, period_type, year, month, week);
CREATE INDEX inspection_targets_officer_idx ON inspection_targets(officer_id, year, month, week);
CREATE INDEX inspection_schedules_date_idx ON inspection_schedules(scheduled_date, status);
CREATE INDEX inspection_reschedules_inspection_idx ON inspection_reschedules(inspection_id, changed_at DESC);
CREATE INDEX inspection_notices_sent_idx ON inspection_notices(status, sent_date);
CREATE INDEX inspection_planning_documents_inspection_idx
  ON inspection_planning_documents(inspection_id, uploaded_at);
CREATE INDEX inspections_plan_idx ON inspections(plan_id, scheduled_date);
CREATE INDEX inspections_target_idx ON inspections(target_id);
CREATE INDEX region_assignments_account_idx ON region_assignments(account_id);
CREATE INDEX account_transfers_time_idx ON account_transfers(effective_at DESC, id);
CREATE INDEX account_transfers_source_idx ON account_transfers(source_account_id, effective_at DESC);
CREATE INDEX account_transfers_target_idx ON account_transfers(target_account_id, effective_at DESC);
CREATE UNIQUE INDEX account_transfer_items_region_idx ON account_transfer_items(transfer_id, region_id)
  WHERE region_id IS NOT NULL;
CREATE UNIQUE INDEX account_transfer_items_facility_idx ON account_transfer_items(transfer_id, facility_id)
  WHERE facility_id IS NOT NULL;
CREATE INDEX assignment_events_region_idx ON assignment_events(region_id, occurred_at DESC, id DESC);
CREATE INDEX assignment_events_facility_idx ON assignment_events(facility_id, occurred_at DESC, id DESC);
CREATE INDEX assignment_events_performer_idx ON assignment_events(performed_by, occurred_at DESC);
CREATE INDEX facility_status_history_facility_time_idx
  ON facility_status_history(facility_id, occurred_at DESC, id DESC);
CREATE UNIQUE INDEX accounts_officer_unique ON accounts(officer_id);
CREATE UNIQUE INDEX facility_violations_open_idx ON facility_violations(facility_id) WHERE status='suspended';
CREATE INDEX facility_violations_facility_time_idx ON facility_violations(facility_id,suspension_at DESC);
CREATE INDEX tasks_assigner_time_idx ON tasks(assigned_by,created_at DESC);
CREATE INDEX tasks_assignee_time_idx ON tasks(assigned_to,created_at DESC);
CREATE INDEX task_messages_task_time_idx ON task_messages(task_id,created_at DESC,id DESC);
CREATE INDEX tasks_due_idx ON tasks(due_at);
CREATE INDEX tasks_completed_idx ON tasks(assigned_to,completed_at);
CREATE UNIQUE INDEX task_assignments_current_uq
  ON task_assignments(task_id) WHERE ended_at IS NULL;
CREATE INDEX task_assignments_assignee_idx
  ON task_assignments(assignee_id,assigned_at DESC,id DESC);
CREATE INDEX task_progress_task_idx ON task_progress(task_id,created_at DESC,id DESC);
CREATE INDEX kpi_targets_period_idx ON kpi_targets(period,account_id);
CREATE INDEX kpi_results_period_idx ON kpi_results(period,account_id);
CREATE INDEX explanations_account_idx
  ON explanations(account_id,requested_at DESC,id DESC);
CREATE INDEX explanations_requester_idx
  ON explanations(requested_by,requested_at DESC,id DESC);
CREATE INDEX data_transfer_jobs_actor_time_idx
  ON data_transfer_jobs(actor_id,created_at DESC,id DESC);
CREATE INDEX data_transfer_jobs_dataset_time_idx
  ON data_transfer_jobs(dataset_id,created_at DESC,id DESC);
CREATE INDEX data_transfer_errors_job_row_idx
  ON data_transfer_errors(job_id,row_number,id);
CREATE INDEX facility_personnel_facility_idx
  ON facility_personnel(facility_id,is_active,is_head,full_name);
CREATE UNIQUE INDEX facility_personnel_active_head_idx
  ON facility_personnel(facility_id) WHERE is_head=1 AND is_active=1;
CREATE INDEX report_schedules_due_idx ON report_schedules(active,next_due_date);
CREATE INDEX report_requests_assignee_due_idx ON report_requests(assignee_id,status,due_date);
CREATE INDEX report_requests_requester_idx ON report_requests(requester_id,status);
CREATE INDEX report_submissions_request_idx ON report_submissions(request_id,submitted_at DESC);
CREATE INDEX notifications_user_time_idx ON notifications(user_id,created_at DESC);
CREATE INDEX violations_facility_idx ON violations(facility_id, detected_on DESC);
CREATE INDEX violations_status_idx ON violations(status, remediation_deadline);
