CREATE OR REPLACE FUNCTION organization_code_required() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.code IS NULL OR length(trim(NEW.code)) NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION '%', TG_ARGV[0] USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER units_code_required BEFORE INSERT OR UPDATE OF code ON units
  FOR EACH ROW EXECUTE FUNCTION organization_code_required('Organization code is required');
CREATE TRIGGER regions_code_required BEFORE INSERT OR UPDATE OF code ON regions
  FOR EACH ROW EXECUTE FUNCTION organization_code_required('Region code is required');

CREATE OR REPLACE FUNCTION units_root_read_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.level = 'ROOT' THEN
    RAISE EXCEPTION 'Root organization is read-only' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER units_root_read_only BEFORE UPDATE ON units
  FOR EACH ROW EXECUTE FUNCTION units_root_read_only();

CREATE OR REPLACE FUNCTION units_no_cycle() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.parent_id IS NOT NULL AND NEW.parent_id <> coalesce(OLD.parent_id, '') AND NEW.parent_id IN (
    WITH RECURSIVE descendants(id) AS (
      SELECT OLD.id UNION SELECT u.id FROM units u JOIN descendants d ON u.parent_id = d.id
    ) SELECT id FROM descendants
  ) THEN
    RAISE EXCEPTION 'Organization hierarchy cannot contain a cycle' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER units_no_cycle BEFORE UPDATE OF parent_id ON units
  FOR EACH ROW EXECUTE FUNCTION units_no_cycle();


CREATE VIEW officer_directory AS
  SELECT id AS officer_id, full_name FROM officers
  UNION ALL
  SELECT a.officer_id, min(a.full_name) AS full_name
  FROM accounts a
  WHERE NOT EXISTS (SELECT 1 FROM officers o WHERE o.id=a.officer_id)
  GROUP BY a.officer_id;
CREATE VIEW facility_overview AS
  SELECT f.id, f.name, f.address, f.status, f.region_id, r.name AS region_name,
    r.unit_id, u.name AS unit_name, f.officer_id, o.full_name AS officer_name
  FROM facilities f
  JOIN regions r ON r.id=f.region_id
  JOIN units u ON u.id=r.unit_id
  LEFT JOIN officer_directory o ON o.officer_id=f.officer_id;


